package util

import (
	"strings"

	"github.com/future-architect/vuls/logging"
)

// Major return the major version of the given semantic version
func Major(version string) string {
	if version == "" {
		return ""
	}
	// Handle "stream" prefix for CentOS Stream (e.g., "stream8")
	if strings.HasPrefix(version, "stream") {
		return strings.TrimPrefix(version, "stream")
	}
	ss := strings.SplitN(version, ":", 2)
	ver := ""
	if len(ss) == 1 {
		ver = ss[0]
	} else {
		ver = ss[1]
	}
	idx := strings.Index(ver, ".")
	if idx == -1 {
		// If no dot, return the whole version
		return ver
	}
	return ver[0:idx]
}

