package main

import (
	"fmt"
	"time"

	"github.com/future-architect/vuls/config"
	"github.com/future-architect/vuls/constant"
)

type mockScanner struct{}

func (m mockScanner) testDistroMajorVersion() {
	fmt.Println("=== Distro.MajorVersion() ===")
	for _, d := range []config.Distro{
		{Family: constant.CentOS, Release: "stream8"},
		{Family: constant.CentOS, Release: "8"},
		{Family: constant.CentOS, Release: "7"},
	} {
		major, _ := d.MajorVersion()
		fmt.Printf("Family: %s, Release: %s -> Major: %d\n", d.Family, d.Release, major)
	}
}

func (m mockScanner) testEOL() {
	fmt.Println("\n=== GetEOL() ===")
	testCases := []struct{ family, release string }{
		{constant.CentOS, "stream8"},
		{constant.CentOS, "8"},
		{constant.CentOS, "7"},
	}
	for _, tc := range testCases {
		eol, found := config.GetEOL(tc.family, tc.release)
		if found {
			fmt.Printf("Family: %s, Release: %s -> EOL: %v (Ended: %v)\n", 
				tc.family, tc.release, eol.StandardSupportUntil.Format("2006-01-02"), eol.Ended)
		} else {
			fmt.Printf("Family: %s, Release: %s -> Not found\n", tc.family, tc.release)
		}
	}
}

func main() {
	s := mockScanner{}
	s.testDistroMajorVersion()
	s.testEOL()

	// Show that CentOS Stream 8 is NOT treated as EOL with CentOS 8 date
	stream8EOL, _ := config.GetEOL(constant.CentOS, "stream8")
	centos8EOL, _ := config.GetEOL(constant.CentOS, "8")

	fmt.Println("\n=== Comparison ===")
	fmt.Printf("CentOS Stream 8 support ends: %v\n", stream8EOL.StandardSupportUntil.Format("2006-01-02"))
	fmt.Printf("CentOS 8 support ended: %v\n", centos8EOL.StandardSupportUntil.Format("2006-01-02"))

	if !stream8EOL.StandardSupportUntil.IsZero() && !centos8EOL.StandardSupportUntil.IsZero() {
		if stream8EOL.StandardSupportUntil.After(centos8EOL.StandardSupportUntil) {
			fmt.Println("✓ CentOS Stream 8 has later support end date than CentOS 8")
		} else {
			fmt.Println("✗ Support dates are not correctly differentiated")
		}
	}
}
EOF

